export function mountMountainStory(link) {
  const figure = document.createElement('figure');
  figure.className = 'rest-scene';
  const scene = document.createElement('button');
  scene.type = 'button';
  scene.className = 'mountain-scene';
  scene.innerHTML = artwork;
  const hint = document.createElement('figcaption');
  hint.className = 'rest-scene-hint';
  hint.setAttribute('aria-live', 'polite');

  function reveal(visible) {
    scene.classList.toggle('revealed', visible);
    scene.setAttribute('aria-pressed', String(visible));
    scene.setAttribute('aria-label', visible ? '再看一次山間的雲霧' : '撥開山霧，和媽媽一起看白龍');
    hint.textContent = visible ? '白龍從祥雲間現身。再點一下，回到山霧中。' : '點一下山間的雲霧。';
  }

  reveal(false);
  scene.addEventListener('click', () => reveal(!scene.classList.contains('revealed')));
  figure.append(scene, hint);
  link.after(figure);
  return () => figure.remove();
}
